import{_ as o,o as i,c as a,a2 as t}from"./chunks/framework.BN2sqjC1.js";const g=JSON.parse('{"title":"ADR-0062 — Vista integrata delle applicazioni accesa di default su Windows e Linux, con ripiego automatico (M22)","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0062-vista-integrata-windows-linux.md","filePath":"adr/0062-vista-integrata-windows-linux.md"}'),n={name:"adr/0062-vista-integrata-windows-linux.md"};function d(c,e,r,s,l,u){return i(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="adr-0062-—-vista-integrata-delle-applicazioni-accesa-di-default-su-windows-e-linux-con-ripiego-automatico-m22" tabindex="-1">ADR-0062 — Vista integrata delle applicazioni accesa di default su Windows e Linux, con ripiego automatico (M22) <a class="header-anchor" href="#adr-0062-—-vista-integrata-delle-applicazioni-accesa-di-default-su-windows-e-linux-con-ripiego-automatico-m22" aria-label="Permalink to &quot;ADR-0062 — Vista integrata delle applicazioni accesa di default su Windows e Linux, con ripiego automatico (M22)&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Stato</strong></td><td>accettata (2026-11-20, decisione dell&#39;owner); recepita in <code>Specifications.md</code> v1.8 (2026-11-20); implementata e rilasciata con la 1.7.3, <strong>non provata su finestre reali</strong>. Emenda <a href="./0056-applicazioni-in-vista-nativa.html">ADR-0056</a> (punti 2, 17, 34-36 e l&#39;alternativa «driver GTK») e <a href="./0060-web-viewer-acceso-di-default.html">ADR-0060</a> (decisione 3)</td></tr><tr><td><strong>Recepito in</strong></td><td><code>Specifications.md</code> v1.8 (2026-11-20): §2.2.1 (riga «Web viewer»), §2.6.6, §3.7, §4.2 (due righe), C.2 e Appendice C.4; <a href="./../spec-v1.8-proposta.html"><code>spec-v1.8-proposta.md</code></a> §3 resta come storia</td></tr><tr><td><strong>Data</strong></td><td>2026-11-19</td></tr><tr><td><strong>Riferimenti spec</strong></td><td>§2.2.1 riga «Web viewer» (<code>Specifications.md:372</code>); §2.6.6 riga <code>features.web_viewer</code> (<code>:596</code>); §3.7 riga «Pagina ospite» (<code>:1543</code>); §4.2 (<code>:1747-1748</code>, <code>:1769</code>); C.2 (<code>:1970</code>); C.4, righe di ADR-0056 e ADR-0060 (<code>:2043</code>, <code>:2048</code>); V-02/D-01; ADR-0029, ADR-0030, ADR-0037, ADR-0045, ADR-0051</td></tr><tr><td><strong>Devia dallo spec?</strong></td><td><strong>sì:</strong> lo spec v1.7 dice che la vista incorporata c&#39;è solo su macOS, che su Windows il driver è spento e che su Linux non esiste. <strong>Recepito nello spec v1.8</strong> (2026-11-20; <a href="./../spec-v1.8-proposta.html"><code>spec-v1.8-proposta.md</code></a> §3): le righe elencate sopra (vedi «Sezioni dello spec da aggiornare»)</td></tr><tr><td><strong>Superfici</strong></td><td>desktop (Windows, Linux, macOS invariato) · workbench web: invariato (voce <code>webapp.embedded</code>, eccezione) · console e cloud: nessuna modifica. Prove automatiche e prove reali in «Prove»</td></tr></tbody></table><h2 id="contesto" tabindex="-1">Contesto <a class="header-anchor" href="#contesto" aria-label="Permalink to &quot;Contesto&quot;">​</a></h2><p>L&#39;owner ha chiesto (2026-11-19) che le applicazioni (file <code>.webapp</code>, ADR-0056) si aprano dentro Clarae anche su Windows e Linux. Oggi:</p><ul><li>La capability <code>embeddedBrowser</code> ha <code>DesktopOS: {&quot;darwin&quot;}</code> (<code>apps/desktop/internal/app/capabilities.go:114</code>).</li><li>Su Windows esiste un driver WebView2 completo ma <strong>spento</strong>: <code>var Supported = experimentalOn(os.Getenv(experimentalEnv))</code> (<code>apps/desktop/internal/shell/nativeview/driver_windows.go:46</code>), con <code>CLARAE_WEBVIEW2_EXPERIMENTAL</code> che vale solo se è esattamente <code>1</code> (<code>winpure.go:25-28</code>). Non è mai stato eseguito su Windows.</li><li>Su Linux <strong>non c&#39;è alcun driver</strong>: <code>driver_other.go</code> (tag <code>!js &amp;&amp; !(darwin &amp;&amp; cgo) &amp;&amp; !windows</code>) ha <code>Supported = false</code>. Lo spike E0 lo aveva compilato in un container senza mai eseguirlo (ADR-0056, contesto).</li><li>Dove non c&#39;è il driver la scheda mostra il riquadro «Apri nel browser» (<code>packages/workbench/src/webapp/BrowserView.tsx:67-74</code>, <code>webapp.card.unavailable</code>).</li></ul><p>ADR-0060 ha acceso <code>features.web_viewer</code> di default ma ha lasciato la vista incorporata solo su macOS (decisione 3). La matrice manuale <a href="./../qa/m18-webview-matrice.html"><code>m18-webview-matrice.md</code></a> non è mai stata eseguita, e questo ADR non lo cambia: il rischio è lo stesso già accettato con ADR-0060 (una funzione non provata sulla finestra reale diventa visibile), e qui si limita con un ripiego automatico e un interruttore di spegnimento.</p><p><strong>Stato del ripiego prima di M22</strong> (verificato sul codice al commit <code>db1b9d6a</code>): un errore di <code>Driver.Create</code> diventava <code>ErrDriver</code> e il binding lo traduceva in <code>webview-failed</code>, mentre <code>BrowserView.tsx:205</code> ripiega sul riquadro «Apri nel browser» solo per <code>webview-unavailable</code> e <code>webview-disabled</code>. Inoltre <code>Manager.driver()</code> teneva il driver una volta creato: un <code>Create</code> fallito non lo marcava come non disponibile, quindi <code>Available()</code> e la capability restavano veri. <strong>Il punto 2 della decisione lo corregge, ed è implementato</strong> (Onda B di M22).</p><h2 id="decisione" tabindex="-1">Decisione <a class="header-anchor" href="#decisione" aria-label="Permalink to &quot;Decisione&quot;">​</a></h2><h3 id="accensione-e-ripiego" tabindex="-1">Accensione e ripiego <a class="header-anchor" href="#accensione-e-ripiego" aria-label="Permalink to &quot;Accensione e ripiego&quot;">​</a></h3><ol><li><p><strong>Vista integrata accesa di default su macOS, Windows e Linux.</strong> <code>DesktopOS</code> di <code>embeddedBrowser</code> diventa <code>{&quot;darwin&quot;,&quot;windows&quot;,&quot;linux&quot;}</code>. Valgono ancora entrambi i cancelli di ADR-0056 punto 17: la capability (che <code>SettingsAPI.Capabilities()</code> spegne se il driver manca) e il flag <code>features.web_viewer</code> del profilo, acceso di default (ADR-0060). Il workbench web resta com&#39;è: la pagina si apre in una scheda del browser.</p></li><li><p><strong>Ripiego automatico.</strong> Se il driver non c&#39;è, il runtime manca o è troppo vecchio, o l&#39;innesto nella finestra fallisce, l&#39;applicazione si apre come oggi con «Apri nel browser»; l&#39;utente non vede un errore. Per ottenerlo:</p><ul><li>un errore di <code>Create</code> che dice «questa piattaforma non può mostrare viste» (runtime assente o sotto il minimo, WebKitGTK sotto il minimo, gerarchia di Wails inattesa) è un errore <strong>di indisponibilità</strong> e diventa <code>webview-unavailable</code>, non <code>webview-failed</code>;</li><li>se <strong>nessuna vista è stata creata</strong> nella sessione, la prima indisponibilità fa marcare al <code>Manager</code> il driver come non disponibile per tutta la sessione: <code>Available()</code> è falso, <code>SettingsAPI.Capabilities()</code> spegne <code>embeddedBrowser</code>, e le schede successive mostrano subito il riquadro senza ritentare e senza richiamare il driver. Se invece il driver aveva già creato una vista, l&#39;indisponibilità vale per quella scheda soltanto (le viste aperte restano);</li><li>un errore transitorio (una pagina che non si carica, una vista che si chiude) resta <code>webview-failed</code> e non spegne il driver.</li></ul><p><strong>Implementato.</strong> Il driver incapsula la sentinella <code>webview.ErrPlatformUnavailable</code> (<code>apps/desktop/internal/webview/driver.go</code>); <code>Manager.Open</code> la riconosce e chiama <code>markUnavailable</code> (<code>manager.go</code>); il binding la traduce in <code>webview-unavailable</code> (<code>bindings_webview.go</code>). Sono di indisponibilità: su Windows un runtime WebView2 assente o troppo vecchio (la prima creazione dell&#39;ambiente che fallisce, o un&#39;interfaccia che il runtime non ha: <code>errMissing</code>); su Linux WebKitGTK sotto 2.40, la finestra che non ha la gerarchia attesa, la sandbox di WebKit che non si può avere (punto 11) (<code>GuestErrUnavailable</code>). Prove: <code>TestAPlatformThatCannotShowViewsIsUnavailableForTheSession</code>, <code>TestAPlatformFailureAfterAViewWasMadeDoesNotEndTheSession</code> e <code>TestAnOrdinaryCreateFailureKeepsTheManagerAvailable</code> (<code>internal/webview/manager_test.go</code>); <code>TestAPlatformThatCannotShowViewsFallsBackToTheSystemBrowser</code> (<code>internal/app/bindings_webview_test.go</code>).</p></li><li><p><strong>Interruttore di spegnimento: <code>CLARAE_WEBVIEW=off</code>.</strong> Sostituisce <code>CLARAE_WEBVIEW2_EXPERIMENTAL</code>, che non è più letta. Spegne solo con il valore <code>off</code> (maiuscole e spazi ai lati non contano: <code>OFF</code>, <code> off</code>); ogni altro valore (vuoto, <code>0</code>, <code>false</code>, <code>no</code>) o la variabile assente lascia acceso. Si legge all&#39;avvio, da <code>New</code>, e <strong>vale solo per i driver di Windows e Linux</strong>: l&#39;helper sta in <code>apps/desktop/internal/shell/nativeview/switch.go</code>, senza build tag, così lo condividono i due driver e lo prova un test su ogni sistema (<code>switch_test.go</code>). <strong>macOS non la legge:</strong> il suo driver è provato (<code>task test-nativeview</code>) e non cambia. Con la variabile <code>off</code> <code>New</code> restituisce <code>nil</code> e le applicazioni si aprono nel browser di sistema.</p></li><li><p><strong>Requisiti minimi.</strong> Windows: runtime WebView2 ≥ <strong>1.0.2210.55</strong> (già imposto dal driver: <code>guest_windows.go:458</code>; un&#39;interfaccia mancante è un errore di indisponibilità), con un controllo anticipato: <code>New</code> chiama <code>loader.RuntimeInstalled()</code> e senza runtime restituisce <code>nil</code>. Linux: <strong>WebKitGTK ≥ 2.40</strong>, nella variante <code>webkit2gtk-4.1</code>, con GTK 3, l&#39;app costruita con cgo e <strong>bubblewrap (<code>bwrap</code>) installato e capace di creare la sandbox</strong> (punto 11). Sotto questi minimi vale il ripiego del punto 2. Le guide dicono i minimi e l&#39;interruttore.</p></li></ol><h3 id="windows" tabindex="-1">Windows <a class="header-anchor" href="#windows" aria-label="Permalink to &quot;Windows&quot;">​</a></h3><ol start="5"><li><strong><code>Supported</code> è <code>true</code>.</strong> Resta il driver di ADR-0056 punti 34-36: copia ridotta del binding WebView2 di Wails v3.1.0 (<code>webview2/</code>), un ambiente e una cartella dati per vault in <code>&lt;dataDir&gt;\\webapps\\&lt;store&gt;</code>, nessun ponte verso l&#39;app. <code>Supported</code> (<code>driver_windows.go:49</code>) è una costante vera, anche con <code>CLARAE_WEBVIEW=off</code>: è ciò che il codice sa fare, e così la pulizia delle sessioni (<code>webviews_sweep.go</code>) non dimentica a un avvio con le viste spente le righe di cui non ha potuto cancellare i dati. A decidere sono <code>New</code> (<code>nil</code> se spento, senza finestra, senza runtime o senza cartella dati) e <code>Create</code>. La firma è <code>nativeview.New(win, dataDir)</code>, con <code>shell.Host.SetDataDir</code> (chiamato da <code>main.go</code>). Cambiano anche: <code>driver_windows_test.go</code> (<code>TestDriverIsOnUnlessSwitchedOff</code>, <code>TestAnOldRuntimeIsAPlatformThatCannotShowViews</code>), <code>capabilities_test.go</code>, <code>winpure_test.go</code> (senza più <code>experimentalOn</code>) e <code>datafolders.go</code> (la cartella dei dati, comune a Windows e Linux).</li></ol><h3 id="linux-driver-webkitgtk" tabindex="-1">Linux: driver WebKitGTK <a class="header-anchor" href="#linux-driver-webkitgtk" aria-label="Permalink to &quot;Linux: driver WebKitGTK&quot;">​</a></h3><ol start="6"><li><strong>Nuovo driver in <code>apps/desktop/internal/shell/nativeview/</code></strong>, con la stessa forma di quello macOS: <code>driver_linux.go</code> (Go, implementa <code>webview.Driver</code> di <code>internal/webview/driver.go</code>) più un file C con cgo (<code>pkg-config: gtk+-3.0 webkit2gtk-4.1</code>), con le callback esportate verso Go. Build tag <code>linux &amp;&amp; cgo &amp;&amp; gtk3 &amp;&amp; !android &amp;&amp; !server &amp;&amp; !purego</code>, gli stessi con cui Wails v3.1.0 costruisce il suo backend GTK3 (<code>pkg/application/linux_cgo_gtk3.go</code>); <code>driver_other.go</code> non copre più quella combinazione. <strong>Il vincolo di build sta anche in testa a <code>guest_linux.c</code> e <code>guest_linux.h</code></strong>: altrimenti il file C resterebbe nel pacchetto di una build senza il driver (GTK 4, <code>purego</code>, senza cgo) e la romperebbe («C source files not allowed when not using cgo»). <code>scripts/linux-vet/vet.sh</code> lo controlla con <code>go list</code> su sei combinazioni di tag e di cgo. File: <code>driver_linux.go</code>, <code>guest_linux.c</code>, <code>guest_linux.h</code>. <strong>Il driver c&#39;è solo per la build <code>-tags production,gtk3</code></strong> (<code>scripts/build-desktop-bin.sh</code> aggiunge <code>gtk3</code> su Linux); una build GTK4, senza cgo o con <code>purego</code> non ha driver, <code>New</code> è <code>nil</code> e vale il ripiego.</li><li><strong>Innesto nella finestra.</strong> Wails costruisce <code>GtkWindow → GtkBox «webview-box» → [barra dei menu] + WebKitWebView</code> (<code>linux_cgo_gtk3.go</code>, <code>windowNew</code>). Il driver ottiene il <code>GtkWindow*</code> da <code>NativeWindow()</code> e, alla prima <code>Create</code>, sul thread GTK (<code>application.InvokeSyncWithResult</code>; <code>graft</code> in <code>guest_linux.c</code>): trova la <code>WebKitWebView</code> figlia del box, la toglie dal box tenendola con un riferimento, la mette in un <code>GtkOverlay</code> impacchettato nel box nella stessa posizione e con lo stesso impacchettamento (expand, fill, spaziatura), rilascia il riferimento e restituisce il fuoco alla web view se l&#39;aveva. <strong>Le viste ospiti sono figli dell&#39;overlay</strong> (<code>gtk_overlay_add_overlay</code>), disegnati e raggiunti dal mouse sopra la web view dell&#39;app; fuori dalle viste i clic arrivano all&#39;app perché lì c&#39;è solo il figlio principale. Non c&#39;è un <code>GtkFixed</code> né una posizione impostata dal driver: la posizione di ogni ospite la dà il segnale <code>get-child-position</code> dell&#39;overlay (punto 8). Il puntatore che Wails tiene alla sua web view resta valido. <strong>Se la gerarchia non è quella attesa</strong> (finestra che non è un <code>GtkWindow</code>, nessun <code>webview-box</code>, zero o più di una <code>WebKitWebView</code> nel box) <strong><code>Create</code> fallisce come indisponibile</strong> (punto 2) e la finestra non viene toccata; il verdetto vale per la sessione.</li><li><strong>Posizione.</strong> I bounds frazionari (0..1, ADR-0056 punto 21) si moltiplicano per l&#39;allocazione dell&#39;overlay dentro <code>get-child-position</code> (<code>onChildPosition</code>): i bordi si arrotondano (non le dimensioni, così due viste che si toccano in frazioni si toccano anche in pixel) e nessuna dimensione scende sotto 1 pixel. <code>SetBounds</code> e la creazione chiedono un nuovo calcolo con <code>gtk_widget_queue_resize</code>; un ridimensionamento della finestra, della barra dei menu o di ciò che sta intorno lo segue l&#39;overlay da solo. La scala HiDPI è gestita da GTK (coordinate logiche).</li><li><strong>Sessioni per vault.</strong> Un <code>WebKitWebContext</code> per <code>store</code>, con un <code>WebKitWebsiteDataManager</code> su <code>&lt;dataDir&gt;/webapps/&lt;store&gt;/{data,cache}</code> (la stessa cartella di Windows, <code>datafolders.go</code>; le cartelle le crea Go, con permessi <code>0700</code>), cookie persistenti in <code>cookies.sqlite</code>, prevenzione del tracciamento (ITP) accesa; <code>PersistentData()</code> è vero. <strong>Il contesto di un vault resta vivo fino a <code>RemoveData</code> o all&#39;uscita dell&#39;app</strong>, così una seconda scheda dello stesso vault condivide cookie e processi. <strong>Durante la cancellazione di uno store</strong> (<code>clearing</code>) una <code>Create</code> dello stesso vault fallisce con <code>GuestErrStoreBusy</code>: un errore ritentabile della vista (<code>webview-failed</code>, la scheda mostra «Riprova»), <strong>non</strong> il ripiego; e <code>onCleared</code> non conferma la cancellazione se nel frattempo esistono viste di quello store. <code>RemoveData</code> cancella i dati che WebKit tiene in memoria, rilascia il contesto e poi cancella la cartella (con nuovi tentativi, fino a 30 s); il <code>Manager</code> ha già chiuso le viste del vault. La pulizia degli archivi orfani (<code>apps/desktop/internal/app/webviews_sweep.go</code>) funziona senza modifiche.</li><li><strong>Navigazione e sicurezza</strong>, con le stesse regole di ADR-0056 punti 26-33: la politica di navigazione è quella Go del <code>Manager</code> (<code>decide-policy</code>); le nuove finestre diventano l&#39;evento <code>webview:new-window</code> e sono annullate; una risposta non visualizzabile è un download, rifiutato; le richieste di permesso sono negate; <strong>il selettore di file è annullato e segnalato</strong> (come permesso <code>file-chooser</code>); l&#39;autenticazione HTTP è annullata; un errore di caricamento (anche di certificato, senza modo di proseguire) è <code>webview:load-error</code>; la fine del processo di rendering è <code>webview:crashed</code>; lo stato della pagina viene dai segnali <code>notify::uri</code>, <code>notify::title</code>, <code>notify::is-loading</code> e <code>back-forward-list::changed</code>. Le impostazioni di <code>WebKitSettings</code> tengono spenti gli strumenti di sviluppo, l&#39;apertura automatica di finestre, la scrittura della console, il tutto schermo, i flussi multimediali e WebRTC; <strong>nessuno script utente, nessun user content manager, nessun ponte verso l&#39;app.</strong> I tasti riservati (ADR-0056 punto 25) si intercettano con <code>key-press-event</code> sulle viste (<code>webview:key</code>; nessuna combinazione con il tasto logo, la tastiera di Linux non ha <code>cmd</code>); <code>SetVisible</code> e <code>Focus</code> restituiscono il fuoco alla web view dell&#39;app quando la vista si nasconde.</li><li><strong>Sandbox di WebKit obbligatoria; ripiego del driver Linux.</strong> Una pagina del web è contenuto non fidato e il suo processo di rendering non gira senza sandbox: ogni contesto è creato con <code>webkit_web_context_set_sandbox_enabled(TRUE)</code>. La sandbox di WebKit è bubblewrap, quindi <code>guestCreate</code> chiama <code>sandboxProblem()</code> (una volta per processo) e, se la sandbox non si può avere, risponde indisponibile: il ripiego del punto 2, cioè «Apri nel browser». Non si ha la sandbox quando: (a) è impostata la variabile <code>WEBKIT_DISABLE_SANDBOX_THIS_IS_DANGEROUS</code> (WebKit la spegnerebbe per tutto il processo); (b) <code>bwrap</code> non è nel <code>PATH</code>; (c) una <strong>sonda di avvio</strong> che replica gli argomenti che WebKit passa a <code>bwrap</code> per un processo web (namespace per hostname, processi, rete e IPC, un <code>/proc</code> proprio, un filtro seccomp che lascia passare tutto) fallisce: tipicamente un container senza privilegi, un sistema con i namespace utente spenti, un emulatore senza seccomp. Anche WebKitGTK sotto 2.40 (<code>New</code> restituisce <code>nil</code>; <code>guestCreate</code> lo ricontrolla) o un innesto fallito fanno fallire <code>Create</code> come indisponibile. Le variabili <code>WEBKIT_*</code> dell&#39;ambiente (per esempio <code>WEBKIT_DISABLE_COMPOSITING_MODE</code>) sono rispettate: il driver non le imposta né le toglie. <strong>Rischio residuo:</strong> se l&#39;avvio del processo web fallisce <em>dopo</em> una sonda riuscita, l&#39;app <strong>abortisce</strong> (<code>g_error</code> di WebKit in <code>readPIDFromPeer</code>): la sonda è perciò esigente quanto l&#39;avvio vero, ma non lo garantisce. <strong>Flatpak e Snap non sono stati provati</strong> (un sistema di sandbox annidato può far fallire la sonda, e allora vale il ripiego, o riuscire e poi fallire l&#39;avvio).</li></ol><h3 id="differenze-dichiarate" tabindex="-1">Differenze dichiarate <a class="header-anchor" href="#differenze-dichiarate" aria-label="Permalink to &quot;Differenze dichiarate&quot;">​</a></h3><ol start="12"><li><p>Rispetto a macOS (ADR-0056 punti 3 e 36 per Windows):</p><table tabindex="0"><thead><tr><th>Aspetto</th><th>macOS</th><th>Windows (WebView2)</th><th>Linux (WebKitGTK)</th></tr></thead><tbody><tr><td>User agent</td><td>suffisso <code>Version/18.0 Safari/605.1.15</code></td><td>quello di Edge</td><td>quello di WebKitGTK, che finisce in <code>Safari/605.1.15</code> (il test live lo controlla), senza il suffisso <code>Version/</code></td></tr><tr><td>Selettore di file</td><td>negato</td><td>non si può negare</td><td><strong>annullato e segnalato</strong> (permesso <code>file-chooser</code>), come su macOS</td></tr><tr><td>Attività per il blocco automatico</td><td>come ADR-0056 punto 19</td><td>solo tasti e fuoco (il mouse non arriva all&#39;host)</td><td>tasti, clic e scorrimento delle viste (al più ogni 5 s)</td></tr><tr><td>Dati di sessione</td><td>contenitore di WebKit; non persistenti prima di macOS 14</td><td><code>&lt;dataDir&gt;\\webapps\\&lt;store&gt;</code>, persistenti</td><td><code>&lt;dataDir&gt;/webapps/&lt;store&gt;/{data,cache}</code>, persistenti; il contesto vive fino a <code>RemoveData</code> o all&#39;uscita</td></tr><tr><td>Autenticazione integrata</td><td>annullata</td><td>NTLM e Kerberos gestiti dal runtime</td><td>annullata</td></tr><tr><td>Innesto nella finestra</td><td>sottovista della content view</td><td>secondo controller WebView2</td><td><strong><code>GtkOverlay</code> che prende il posto della web view di Wails nel <code>webview-box</code>; dipende dalla gerarchia di Wails v3.1.0</strong> (punto 7)</td></tr><tr><td>Distinzione frame / pagina</td><td>il driver conosce il frame</td><td>il driver conosce il frame</td><td><strong>in parte sconosciuto</strong> (punto 13)</td></tr><tr><td>Build che lo ha</td><td>cgo</td><td>tutte</td><td>solo <code>-tags production,gtk3</code> con cgo; non GTK4, non <code>purego</code></td></tr><tr><td>Versione minima</td><td>(del sistema)</td><td>WebView2 ≥ 1.0.2210.55</td><td>WebKitGTK ≥ 2.40 (<code>webkit2gtk-4.1</code>)</td></tr></tbody></table></li><li><p><strong>Su Linux il frame di una navigazione è in parte sconosciuto.</strong> WebKitGTK non dice a quale frame appartiene una decisione di navigazione: quella di un frame dentro la pagina è uguale a quella del frame principale (nessun frame nell&#39;azione, nessun nome, nessun <code>Sec-Fetch-Dest</code> a quel punto; il test live lo mostra). Il core lo modella con <code>webview.FrameKind</code> (<code>FrameMain</code>, <code>FrameSub</code>, <code>FrameUnknown</code>), con la politica <code>webview.FramePolicy(id, url, frame, redirect)</code> e la notifica <code>webview.MainFrameNotice</code>, e con l&#39;interfaccia opzionale <strong><code>webview.FrameAwareDriver</code></strong> (<code>SetFramePolicy</code>), che <strong>solo il driver Linux</strong> implementa (<code>internal/webview/driver.go</code>, <code>manager.go</code>; macOS e Windows conoscono il frame e usano la <code>Policy</code> di prima). Il driver Linux (<code>frameOf</code> in <code>guest_linux.c</code>) dice <code>FrameSub</code> per gli schemi <code>about:</code>, <code>blob:</code> e <code>data:</code> (ciò con cui le pagine costruiscono i frame) e <code>FrameUnknown</code> per tutto il resto. Per <code>FrameUnknown</code> il <code>Manager</code>:</p><ul><li>applica le <strong>regole del frame principale</strong>, che sono le più severe (un indirizzo locale da una pagina pubblica è rifiutato; uno schema diverso da <code>http</code> e <code>https</code> è rifiutato);</li><li><strong>non scrive <code>curPrivate</code></strong> e segnala un rifiuto con <code>MainFrame: false</code>: l&#39;effetto collaterale che una prima versione aveva su <code>curPrivate</code> <strong>non c&#39;è più</strong>;</li><li>impara dove sta il frame principale da <code>notify::uri</code> (<code>MainFrameNotice</code> → <code>mainFrameStarted</code>), che aggiorna <code>curPrivate</code>;</li><li>tiene lo stato <code>pendingPublic</code>: dopo una navigazione sconosciuta verso un host <strong>pubblico</strong>, il passo successivo di un <strong>redirect</strong> (<code>redirect</code> vero) verso un host privato è rifiutato, qualunque fosse la pagina di partenza (una catena che esce da un host privato passando per uno pubblico non può rientrare nella rete privata per redirect); lo stato si azzera quando il frame principale dice dov&#39;è;</li><li>rifiuta un <strong>iframe verso un host privato da una pagina pubblica</strong>.</li></ul><p>La scelta sbaglia dalla parte del rifiuto: non apre mai l&#39;accesso a una rete privata. Prove: <code>TestUnknownFrameFollowsTheRulesOfTheTopFrameWithoutMovingIt</code>, <code>TestRedirectOfUnknownFrameDoesNotReturnToThePrivateNetwork</code> e <code>TestTopFrameStillMovesThePage</code> (<code>manager_test.go</code>), più il test live dei frame.</p><p>L&#39;innesto GTK sposta un widget di Wails: un aggiornamento di Wails va ricontrollato (test live e controllo della gerarchia, con ripiego).</p></li></ol><h3 id="prove" tabindex="-1">Prove <a class="header-anchor" href="#prove" aria-label="Permalink to &quot;Prove&quot;">​</a></h3><ol start="14"><li><p><strong>Automatiche</strong> (dentro <code>task ci</code> salvo dove detto):</p><ul><li><code>internal/webview/manager_test.go</code>: <code>TestAPlatformThatCannotShowViewsIsUnavailableForTheSession</code>, <code>TestAPlatformFailureAfterAViewWasMadeDoesNotEndTheSession</code>, <code>TestAnOrdinaryCreateFailureKeepsTheManagerAvailable</code> e i tre dei frame (punto 13);</li><li><code>internal/app/bindings_webview_test.go</code>: <code>TestAPlatformThatCannotShowViewsFallsBackToTheSystemBrowser</code>; <code>capabilities_test.go</code>: la tabella con <code>darwin</code>, <code>windows</code> e <code>linux</code>;</li><li><code>internal/shell/nativeview/switch_test.go</code> (<code>TestDisableSwitch</code>, <code>TestEnvironmentSwitch</code>), <code>datafolders_test.go</code> (<code>TestWebappsDir</code>) e, per Windows, <code>driver_windows_test.go</code> (<code>TestDriverIsOnUnlessSwitchedOff</code>, <code>TestAnOldRuntimeIsAPlatformThatCannotShowViews</code>);</li><li><code>task vet-windows</code> (esiste) e il nuovo <strong><code>task vet-linux</code></strong>, che in un container Docker (<code>scripts/linux-vet</code>, con <code>libgtk-3-dev</code> e <code>libwebkit2gtk-4.1-dev</code>) esegue <code>go vet -tags gtk3</code>, compila i test di <code>internal/shell</code>, <code>internal/app</code> e <code>internal/webview</code>, compila il file C con <code>-Wall -Wextra</code> e controlla con <code>go list</code> che il pacchetto si elenchi in sei combinazioni di tag e di cgo (anche senza il driver); sta in <code>task ci</code> dopo <code>vet-windows</code>. <code>LINUX_ARCH=arm64</code> lo rende molto più veloce su un Mac Apple silicon;</li><li>a mano, non in <code>task ci</code>: <strong><code>task test-nativeview-linux</code></strong>, 14 test live (<code>driver_linux_live_test.go</code>, tag <code>nativeviewtest</code>) contro una finestra vera di Wails su GTK3 sotto Xvfb, in Docker, <strong>con la sandbox di WebKit accesa</strong>: innesto, pagina e user agent, posizione con il ridimensionamento, nulla dell&#39;app raggiungibile, schemi e frame rifiutati, nuove finestre, download e permessi, certificati, autenticazione, tasti riservati, fuoco e attività, sessioni per vault e cancellazione dei dati, store in cancellazione che rifiuta nuove viste, aperture ripetute, chiusura con le viste aperte. Il container parte con <code>--init --cap-add SYS_ADMIN --cap-add NET_ADMIN --security-opt seccomp=unconfined --security-opt systempaths=unconfined</code> (o <code>--privileged</code>): bubblewrap deve poter creare i namespace. <strong>Un container amd64 su un Mac arm64 non può</strong> (l&#39;emulatore non ha seccomp): lì si usa <code>LINUX_ARCH=arm64</code>. Opzioni: <code>RUN=&lt;regexp&gt;</code>, <code>NO_MENU=1</code> (senza barra dei menu), <code>CLARAE_NATIVEVIEW_CFLAGS=-DCLARAE_NATIVEVIEW_TRACE</code> (traccia delle navigazioni). Il test disattiva solo i percorsi GPU (<code>WEBKIT_DISABLE_COMPOSITING_MODE</code>), per sé: l&#39;app non li imposta mai; <code>live.sh</code> toglie <code>WEBKIT_DISABLE_SANDBOX_THIS_IS_DANGEROUS</code> e il test fallisce se è impostata. <strong>Esito riportato dagli sviluppatori: tutti i test live verdi su arm64 con la sandbox accesa.</strong> Il vecchio esito su amd64 era senza sandbox e <strong>non vale più</strong>.</li></ul><p><strong>Non provati:</strong> Windows a runtime (nessuna macchina Windows); Linux su Wayland reale o con GPU reale; i clic e la tastiera di un utente vero; <strong>Flatpak e Snap</strong>; l&#39;amd64 con la sandbox. Il test live Linux gira su X11 sotto Xvfb, su arm64.</p></li><li><p><strong>Reali, a carico dell&#39;owner:</strong> la matrice <a href="./../qa/m18-webview-matrice.html"><code>m18-webview-matrice.md</code></a> (aggiornata nell&#39;Onda D: Windows senza interruttore, casi nuovi di Linux su X11, su Wayland e con GPU reale, ripiego senza runtime, senza <code>bwrap</code>, con la variabile che disattiva la sandbox e con <code>CLARAE_WEBVIEW=off</code>, Flatpak e Snap, redirect verso la rete privata e iframe). Fino alla loro esecuzione, <strong>i driver di Windows e Linux non sono provati su una finestra reale</strong> e le guide lo dicono.</p></li><li><p><strong>Parità</strong> (ADR-0045): la voce <code>webapp.embedded</code> di <code>shared/parity/features.yaml</code> dice «macOS, Windows e Linux» e porta le prove nuove; <code>task gen</code> rigenera <code>capabilities.gen.ts</code>; il workbench resta un&#39;eccezione dichiarata.</p></li></ol><h3 id="sezioni-dello-spec-da-aggiornare-a-cura-dell-owner" tabindex="-1">Sezioni dello spec da aggiornare (a cura dell&#39;owner) <a class="header-anchor" href="#sezioni-dello-spec-da-aggiornare-a-cura-dell-owner" aria-label="Permalink to &quot;Sezioni dello spec da aggiornare (a cura dell&#39;owner)&quot;">​</a></h3><p>Righe della v1.7 che cambiano; il testo applicato è in <a href="./../spec-v1.8-proposta.html"><code>../spec-v1.8-proposta.md</code></a> §3, <strong>recepito in <code>Specifications.md</code> v1.8 il 2026-11-20</strong>.</p><ul><li><strong>§2.2.1, riga «Web viewer»</strong> (<code>:372</code>): le frasi «Windows: un driver scritto e compilato ma spento…» e «Linux: nessun driver, browser di sistema» diventano il driver acceso di default su Windows e Linux, con ripiego automatico e <code>CLARAE_WEBVIEW=off</code>.</li><li><strong>§2.6.6</strong> (<code>:596</code>): la nota «serve anche il browser incorporato (macOS)» dice «(macOS, Windows, Linux)».</li><li><strong>§3.7, «Pagina ospite»</strong> (<code>:1543</code>): «driver macOS» diventa i tre driver; le regole non cambiano.</li><li><strong>§4.2</strong> (<code>:1748</code> e <code>:1769</code>): <code>shell/nativeview/</code> elenca macOS, Windows e Linux; <code>embeddedBrowser</code> non è più «solo desktop su macOS».</li><li><strong>C.2</strong> (<code>:1970</code>): «solo su macOS; altrove si apre nel browser di sistema» → «su macOS, Windows e Linux; altrove, o se il driver o il runtime mancano, nel browser di sistema». La riga «Webview diversi per OS» (<code>:1969</code>) può rinviare a questo ADR.</li><li><strong>C.4</strong> (<code>:2043</code>, <code>:2048</code>): note nelle righe di ADR-0056 e ADR-0060; nuova riga di ADR-0062.</li></ul><h2 id="alternative-considerate" tabindex="-1">Alternative considerate <a class="header-anchor" href="#alternative-considerate" aria-label="Permalink to &quot;Alternative considerate&quot;">​</a></h2><ul><li><strong>Lasciare il driver di Windows spento e il ripiego solo su Windows/Linux</strong> — scartata dall&#39;owner: le due piattaforme restano senza la funzione e il driver compilato non si prova mai.</li><li><strong>Accenderli solo con un&#39;opzione del profilo (flag per piattaforma)</strong> — scartata: è già il caso del flag <code>features.web_viewer</code>; un secondo interruttore nel profilo moltiplica le combinazioni. L&#39;interruttore locale <code>CLARAE_WEBVIEW=off</code> basta per la diagnosi sul singolo computer.</li><li><strong>Mantenere <code>CLARAE_WEBVIEW2_EXPERIMENTAL</code> per Windows e aggiungere una variabile per Linux</strong> — scartata: il nome dice «sperimentale» e «WebView2», e due variabili per la stessa cosa sono un errore in attesa.</li><li><strong>Un driver GTK come finestra figlia o <code>GtkPlug</code></strong> — scartata: la finestra resta una (A-03); la vista è un figlio della stessa finestra, come negli altri due driver.</li><li><strong>Il piano iniziale: un livello <code>GtkFixed</code> sopra l&#39;overlay, con <code>gtk_fixed_move</code> e il segnale <code>size-allocate</code></strong> — scartata in fase di implementazione: l&#39;overlay chiede la posizione di ogni figlio con <code>get-child-position</code>, e così segue da solo il ridimensionamento della finestra e della barra dei menu, senza un livello in più né segnali da tenere allineati.</li><li><strong>Aggiungere la vista a un contenitore creato da Clarae invece di spostare la <code>WebKitWebView</code> di Wails</strong> — non possibile con le API pubbliche di Wails v3.1.0: il box e la web view sono creati dentro <code>windowNew</code>. Lo spostamento dentro un <code>GtkOverlay</code> è il costo dell&#39;innesto, con il ripiego se la gerarchia cambia.</li><li><strong>Ripiego solo a livello dell&#39;interfaccia (<code>webview-failed</code> come <code>unavailable</code>)</strong> — scartata: un errore transitorio non deve spegnere la funzione per la sessione, e la capability deve dire il vero (<code>Capabilities()</code>).</li></ul><h2 id="conseguenze" tabindex="-1">Conseguenze <a class="header-anchor" href="#conseguenze" aria-label="Permalink to &quot;Conseguenze&quot;">​</a></h2><ul><li>Windows e Linux hanno la scheda con barra e pagina incorporata, come macOS; i sistemi con driver mancante o runtime non adatto vedono il riquadro «Apri nel browser», senza errori.</li><li><strong>Rischio accettato: due driver mai eseguiti diventano il comportamento di default.</strong> Lo limitano il ripiego automatico, <code>CLARAE_WEBVIEW=off</code>, il flag <code>features.web_viewer</code> del profilo e la matrice dell&#39;owner. Un difetto che non fa fallire <code>Create</code> (una vista sbagliata di posizione, il fuoco, lo sfarfallio) non è coperto dal ripiego.</li><li><strong>Dipendenza da Wails v3.1.0</strong> (ADR-0051, accettato il 2026-11-20 e recepito nello spec v1.8: V-07 e D-07 dicono Wails v3.1.0): l&#39;innesto GTK conosce la gerarchia di <code>windowNew</code> (un <code>GtkBox</code> di nome <code>webview-box</code> con una sola <code>WebKitWebView</code>). Ogni aggiornamento di Wails va ricontrollato con il test live Linux.</li><li>Nuove dipendenze di build per Linux: <code>libgtk-3-dev</code> e <code>libwebkit2gtk-4.1-dev</code> (già usate per costruire Wails v3 su Linux). Per chi esegue l&#39;app Linux serve WebKitGTK ≥ 2.40 e <strong>bubblewrap</strong> (<code>bwrap</code>) funzionante: in un container o in un ambiente senza namespace utente la vista non parte e valgono «Apri nel browser» e il ripiego.</li><li>La guida utente e la guida admin (Applicazioni) dicono i tre sistemi, i requisiti e <code>CLARAE_WEBVIEW=off</code>; il CHANGELOG lo annuncia; la matrice di QA <a href="./../qa/m18-webview-matrice.html"><code>m18-webview-matrice.md</code></a> ha i casi nuovi (Onda D, fatta).</li><li>Su Linux il frame di una navigazione è in parte sconosciuto (punto 13: regole del frame principale, senza effetto su <code>curPrivate</code>) e il selettore di file è annullato: differenze dichiarate rispetto a macOS e Windows.</li><li><strong>Rischio residuo della sandbox:</strong> se il processo web non parte dopo una sonda riuscita, WebKit abortisce l&#39;app; il ripiego non lo copre. Flatpak e Snap non sono provati.</li><li><strong>Da rivedere:</strong> il default di <code>CLARAE_WEBVIEW</code> su macOS (oggi non letta), quando la matrice sarà eseguita su Windows e Linux; la differenza del selettore di file su Linux.</li></ul>',25)])])}const v=o(n,[["render",d]]);export{g as __pageData,v as default};
